5	/* ---- UART2 (console) --------------------------------------------------- */
6	
7	#define UART_THR (*(volatile uint32_t*) 0xf0300020UL)
8	#define UART_LSR (*(volatile uint32_t*) 0xf0300034UL)
9	#define UART_LSR_THRE 0x20u
10	
11	void htif_uart_putc(char c)
12	{
13	  while (!(UART_LSR & UART_LSR_THRE))
14	    ;
15	  UART_THR = (uint32_t) (unsigned char) c;
16	}
17	
18	/* ---- SimControl syscall window ------------------------------------------ */
19	
20	#define SYSCALL_GO_ADDR 0xe0080028UL
21	#define WIN_SLOTS ((volatile uint64_t*) 0xe0080800UL)
22	
23	/* Copy guest memory into the window data area (u64 stores only; the final
24	 * partial word over-stores into window slack, which is scratch). */
25	void htif_win_store(size_t woff, const void* src, size_t len)
26	{
27	  const unsigned char* s = (const unsigned char*) src;
28	  volatile uint64_t* w = (volatile uint64_t*) (WIN_DATA_VA + woff);
29	  while (len) {
30	    size_t n = len < 8 ? len : 8;
31	    uint64_t word = 0;
32	    for (size_t i = 0; i < n; ++i)
33	      word |= (uint64_t) s[i] << (8 * i);
34	    *w++ = word;
35	    s += n;
36	    len -= n;
37	  }
38	}
39	
40	/* Copy from the window data area into guest memory (u64 loads only). */
41	void htif_win_load(void* dst, size_t woff, size_t len)
42	{
43	  unsigned char* d = (unsigned char*) dst;
44	  volatile const uint64_t* w = (volatile const uint64_t*) (WIN_DATA_VA + woff);
45	  while (len) {
46	    size_t n = len < 8 ? len : 8;
47	    uint64_t word = *w++;
48	    for (size_t i = 0; i < n; ++i)
49	      d[i] = (unsigned char) (word >> (8 * i));
50	    d += n;
51	    len -= n;
52	  }
53	}
54	
55	size_t htif_win_store_str(size_t woff, const char* s)
56	{
57	  size_t len = 0;
58	  while (s[len])
59	    ++len;
60	  ++len; /* NUL */
61	  if (woff + len > WIN_DATA_SIZE)
62	    return (size_t) -1;
63	  htif_win_store(woff, s, len);
64	  return (woff + len + 7) & ~(size_t) 7;
65	}
