83	intptr_t htif_call_str(uint64_t n, const char* s, uint64_t a1, uint64_t a2)
84	{
85	  if (htif_win_store_str(0, s) == (size_t) -1)
86	    return -1;
87	  return htif_syscall(n, WIN_DATA_VA, a1, a2, 0);
88	}
