90	intptr_t htif_call_str2(uint64_t n, const char* s0, const char* s1)
91	{
92	  size_t off1 = htif_win_store_str(0, s0);
93	  if (off1 == (size_t) -1 || htif_win_store_str(off1, s1) == (size_t) -1)
94	    return -1;
95	  return htif_syscall(n, WIN_DATA_VA, WIN_DATA_VA + off1, 0, 0);
96	}
