98	ssize_t htif_write(int fd, const void* ptr, size_t len)
99	{
100	  const unsigned char* p = (const unsigned char*) ptr;
101	  size_t done = 0;
102	  while (done < len) {
103	    size_t n = len - done;
104	    if (n > WIN_DATA_SIZE)
105	      n = WIN_DATA_SIZE;
106	    htif_win_store(0, p + done, n);
107	    intptr_t r = htif_syscall(VH_SYS_WRITE, fd, WIN_DATA_VA, n, 0);
108	    if (r < 0)
109	      return done ? (ssize_t) done : (ssize_t) r;
110	    done += (size_t) r;
111	    if ((size_t) r < n)
112	      break; /* short write */
113	  }
114	  return (ssize_t) done;
115	}
116	
117	ssize_t htif_read(int fd, void* buf, size_t len)
118	{
119	  unsigned char* p = (unsigned char*) buf;
120	  size_t done = 0;
121	  while (done < len) {
122	    size_t n = len - done;
123	    if (n > WIN_DATA_SIZE)
124	      n = WIN_DATA_SIZE;
125	    intptr_t r = htif_syscall(VH_SYS_READ, fd, WIN_DATA_VA, n, 0);
126	    if (r < 0)
127	      return done ? (ssize_t) done : (ssize_t) r;
128	    if (r > 0)
129	      htif_win_load(p + done, 0, (size_t) r);
130	    done += (size_t) r;
131	    if ((size_t) r < n)
132	      break; /* EOF or short read */
133	  }
134	  return (ssize_t) done;
135	}
