612	    case SYS_getpid:
613	    case SYS_gettid:
614	      ret = 1;
615	      break;
616	    case SYS_getuid:
617	    case SYS_geteuid:
618	    case SYS_getgid:
619	    case SYS_getegid:
620	      ret = 0;
